mapper.update:
UPDATE ${table}
SET status = 'PROCESSING', result = NULL, error = NULL, finished_at = NULL,
    expire_at = #{expireAt}, host = #{host}, gmt_modified = CURRENT_TIMESTAMP
WHERE scope = #{scope} AND idem_key = #{idemKey}
  AND (status = 'FAILED' OR expire_at < #{now}
       OR (status = 'PROCESSING' AND gmt_modified < #{staleBefore}))

UPDATE ${table}
SET status = 'DONE', result = #{result}, finished_at = CURRENT_TIMESTAMP
WHERE scope = #{scope} AND idem_key = #{idemKey}
  AND status = 'PROCESSING' AND expire_at = #{claimExpireAt}

UPDATE ${table}
SET status = 'FAILED', error = #{error}, finished_at = CURRENT_TIMESTAMP
WHERE scope = #{scope} AND idem_key = #{idemKey}
  AND status = 'PROCESSING' AND expire_at = #{claimExpireAt}
